# Read actual candidate geometry/labels/paint bindings in bounded native batches.
import json
from operate import OUT,script
cfg=json.loads((OUT/'candidate-target.json').read_text());frames=[]
for f in sorted(OUT.glob('generate-*.receipt.txt')):frames.extend(json.loads(f.read_text())['frames'])
selected=[f for f in frames if f[0] in ['A12','E1','C8','C9','B1','C1','C3','C7','D1','D2','D3','E4']]
for i in range(0,len(selected),4):
 subset=selected[i:i+4]
 code="""const page=await figma.getNodeByIdAsync('4:8829');await page.loadAsync();const sec=await figma.getNodeByIdAsync('1589:63500');if(sec.id==='1554:62573'||sec.parent.id!==page.id)throw Error('candidate guard');const out=[];for(const [key,dev,id] of INPUT){const f=await figma.getNodeByIdAsync(id);if(f.parent.id!==sec.id)throw Error('frame ownership');const vp=f.findChild(n=>n.name==='Scrollable task viewport');const dock=f.findChild(n=>n.name==='Fixed action dock');const comp=vp?.children[0];const rect=n=>n?{id:n.id,x:n.x,y:n.y,width:n.width,height:n.height,visible:n.visible,clipsContent:n.clipsContent,overflowDirection:n.overflowDirection}:null;const boxes=f.findAll(n=>n.name.startsWith('Value / ')).map(n=>({name:n.name,...rect(n),text:n.findAllWithCriteria({types:['TEXT']}).map(t=>({text:t.characters,resize:t.textAutoResize,height:t.height}))}));const disabled=f.findAll(n=>n.name.startsWith('Action ·')&&n.name.endsWith(' · disabled')).map(n=>{const t=n.findOne(x=>x.type==='TEXT');return {id:n.id,label:t.characters,instanceOpacity:n.opacity,textOpacity:t.opacity,background:n.fills,foreground:t.fills,boundVariables:t.boundVariables,instanceModes:n.explicitVariableModes,textModes:t.explicitVariableModes};});out.push({key,dev,id,frame:rect(f),viewport:rect(vp),content:rect(comp),dock:rect(dock),text:f.findAllWithCriteria({types:['TEXT']}).map(t=>t.characters),memberRows:f.findAll(n=>n.name.startsWith('Member item ·')||n.name.startsWith('Member row ·')).map(n=>({name:n.name,...rect(n)})),ledgerRows:f.findAll(n=>n.name.startsWith('Ledger item ·')||n.name.startsWith('Ledger row ·')).map(n=>({name:n.name,...rect(n)})),sheets:f.children.filter(n=>n.name==='Dialog'||n.name==='Bottom sheet').map(rect),boxes,disabled});}return out;""".replace('INPUT',json.dumps(subset,ensure_ascii=False))
 script(f'geometry-{i//4:02d}',code);print(i,flush=True)
